```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='search' AND span_name='geo.Geo/Nearby' GROUP BY 1,2,3,4 ORDER BY 1",
          "claim": "search's client span to geo.Geo/Nearby rose from p50 0.39ms normal to p50 1543ms abnormal, p95 2933ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name IN ('geo.Geo/Nearby','search.Search/Nearby') GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "geo's own server span stays about 0.12ms p50 while search's client call to it takes about 1.5s, so the delay is on the wire."
        },
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM (SELECT 'abn' src, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1,2,3,4 ORDER BY 1",
          "claim": "search's calls to rate are unchanged (p95 about 7.7ms in both periods), so the delay is specific to the geo connection."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, avg(value) avg_v, max(value) mx FROM abnormal_metrics WHERE service_name IN ('search','geo') AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "search and geo CPU and memory stay low during the incident, so no resource saturation explains the delay."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name IN ('geo.Geo/Nearby','search.Search/Nearby') GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "The slow leg is the search-to-geo connection: geo's server span is about 0.2ms p95 while search's Nearby server span is about 2.9s."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "frontend's /hotels server spans rise to p95 about 2.9s, matching frontend's client calls to search at about 2.9s."
        }
      ]
    }
  ]
}
```

